
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_b97_2_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_b97_2", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.544260492786075e+00, -3.474953347157824e+00, -3.377893811621727e+00, -3.243567617886524e+00, -3.060817674754953e+00, -2.818273471861663e+00, -2.507805220676463e+00, -2.131180681357263e+00, -1.710524259268492e+00, -1.294363896104531e+00, -8.970186065818730e-01, -6.062073564960193e-01, -5.256166934655128e-01, -4.298588505612233e-01, -3.081127683451268e-01, -1.933113251983101e-01, -1.268529004054588e-01, -6.306697377534042e-02, -1.557259804030078e-02, -1.849109424209907e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


